const settingsDialog=document.getElementById('scene-settings-dialog'),settingsButton=document.getElementById('scene-settings'),promptForm=document.getElementById('prompt-composer'),promptText=document.getElementById('prompt-text');
let settingsReturnFocus=null;
function updateAppearanceControls(){settingsDialog.querySelectorAll('input[name="scene-mode"]').forEach(r=>r.checked=r.value===appearanceMode);document.getElementById('mode-note').textContent=appearanceMode==='clock'?'Slider mode follows your chosen time, not the live clock.':appearanceMode==='light'?'Always light: scene fixed at noon. Your slider time is retained for Slider mode.':'Always dark: scene fixed at midnight. Your slider time is retained for Slider mode.';updateSceneTime();}
settingsDialog.querySelectorAll('input[name="scene-mode"]').forEach(r=>r.addEventListener('change',()=>{if(r.checked&&setAppearanceMode(r.value))updateAppearanceControls()}));
settingsButton.addEventListener('click',()=>{closeMenu();settingsReturnFocus=document.activeElement;settingsDialog.showModal();document.body.classList.add('settings-open');document.getElementById('settings-close').focus();});
document.getElementById('settings-close').addEventListener('click',()=>settingsDialog.close());
settingsDialog.addEventListener('close',()=>{document.body.classList.remove('settings-open');if(settingsReturnFocus?.isConnected)settingsReturnFocus.focus();else settingsButton.focus();});
settingsDialog.addEventListener('click',event=>{if(event.target!==settingsDialog)return;const r=settingsDialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)settingsDialog.close();});
settingsDialog.addEventListener('keydown',event=>{if(event.key!=='Tab')return;const targets=[...settingsDialog.querySelectorAll('button:not([hidden]),input:not([disabled]),a[href]')].filter(el=>el.getClientRects().length);const first=targets[0],last=targets.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}});
function submitPrototype(event){event?.preventDefault();document.getElementById('composer-status').textContent=promptText.value.trim()?'Prototype only—nothing was sent. Your draft remains here.':'Write a question to try the layout. Nothing will be sent.';promptText.focus();}
promptForm.addEventListener('submit',submitPrototype);document.getElementById('prompt-submit').addEventListener('click',submitPrototype);
promptText.addEventListener('keydown',event=>{if(event.key==='Enter'&&(event.ctrlKey||event.metaKey)&&!event.isComposing)submitPrototype(event)});
promptText.addEventListener('input',()=>{promptText.style.height='auto';promptText.style.height=Math.min(150,promptText.scrollHeight)+'px'});
function updateKeyboardOffset(){const v=window.visualViewport;const editing=document.activeElement===promptText;const offset=v&&editing?Math.max(0,window.innerHeight-v.height-v.offsetTop):0;document.documentElement.style.setProperty('--keyboard-offset',Math.round(offset)+'px');}
window.visualViewport?.addEventListener('resize',updateKeyboardOffset);window.visualViewport?.addEventListener('scroll',updateKeyboardOffset);promptText.addEventListener('focus',updateKeyboardOffset);promptText.addEventListener('blur',()=>{document.documentElement.style.setProperty('--keyboard-offset','0px')});
updateAppearanceControls();
